const std = @import("std");
const builtin = @import("builtin");

const DEFAULT_NUM_RESULTS: u32 = 8;
const DEFAULT_HIGHLIGHT_CHARS: u32 = 4000;
const EXA_BASE_URL = "";
const SEARCH_ENDPOINT = "/search";

const IntegrationConfig = struct {
    exa_api_key: []const u8,
    user_provided_api_key: bool,
};

const Logger = struct {
    request_id: []const u8,
    tool_name: []const u8,
    allocator: std.mem.Allocator,

    fn start(self: *const Logger, msg: []const u8) void {
        std.log.info("[{s}][{s}] start: {s}", .{ self.request_id, self.tool_name, msg });
    }
    fn log(self: *const Logger, msg: []const u8) void {
        std.log.info("[{s}][{s}] {s}", .{ self.request_id, self.tool_name, msg });
    }
    fn logFmt(self: *const Logger, comptime fmt: []const u8, args: anytype) void {
        const buf = std.fmt.allocPrint(self.allocator, fmt, args) catch return;
        defer self.allocator.free(buf);
        std.log.info("[{s}][{s}] {s}", .{ self.request_id, self.tool_name, buf });
    }
    fn complete(self: *const Logger) void {
        std.log.info("[{s}][{s}] complete", .{ self.request_id, self.tool_name });
    }
    fn err(self: *const Logger, e: anyerror) void {
        std.log.err("[{s}][{s}] error: {s}", .{ self.request_id, self.tool_name, @errorName(e) });
    }
};

fn createRequestLogger(allocator: std.mem.Allocator, request_id: []const u8, tool_name: []const u8) Logger {
    return .{ .request_id = request_id, .tool_name = tool_name, .allocator = allocator };
}

fn checkpoint(name: []const u8) void {
    std.log.debug("checkpoint: {s}", .{name});
}

fn randomSuffix(allocator: std.mem.Allocator) ![]u8 {
    var prng = std.Random.DefaultPrng.init(@bitCast(std.time.nanoTimestamp()));
    const rand = prng.random();
    const chars = "abcdefghijklmnopqrstuvwxyz0123456789";
    var buf = try allocator.alloc(u8, 5);
    for (0..5) |i| {
        buf[i] = chars[rand.intRangeLessThan(usize, 0, chars.len)];
    }
    return buf;
}

fn makeRequestId(allocator: std.mem.Allocator) ![]u8 {
    const ts: i64 = std.time.milliTimestamp();
    const suffix = try randomSuffix(allocator);
    defer allocator.free(suffix);
    return try std.fmt.allocPrint(allocator, "deep_search_exa-{d}-{s}", .{ ts, suffix });
}

const HttpResponse = struct {
    status: u16,
    body: []u8,

    fn deinit(self: *HttpResponse, allocator: std.mem.Allocator) void {
        allocator.free(self.body);
    }
};

fn httpPost(allocator: std.mem.Allocator, url: []const u8, headers: []const std.http.Header, body: []const u8) !HttpResponse {
    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse(url);

    var server_header_buffer: [16 * 1024]u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &server_header_buffer,
        .extra_headers = headers,
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = body.len };
    try req.send();
    try req.writeAll(body);
    try req.finish();
    try req.wait();

    var resp_body = std.ArrayList(u8).init(allocator);
    errdefer resp_body.deinit();

    var buf: [8192]u8 = undefined;
    while (true) {
        const n = try req.reader().read(&buf);
        if (n == 0) break;
        try resp_body.appendSlice(buf[0..n]);
    }

    return HttpResponse{
        .status = @intFromEnum(req.response.status),
        .body = try resp_body.toOwnedSlice(),
    };
}

fn retryWithBackoff(
    allocator: std.mem.Allocator,
    url: []const u8,
    headers: []const std.http.Header,
    body: []const u8,
) !HttpResponse {
    var attempt: u32 = 0;
    const max_attempts: u32 = 4;
    var delay_ms: u64 = 500;
    while (true) : (attempt += 1) {
        const result = httpPost(allocator, url, headers, body) catch |e| {
            if (attempt + 1 >= max_attempts) return e;
            std.time.sleep(delay_ms * std.time.ns_per_ms);
            delay_ms *= 2;
            continue;
        };
        if (result.status >= 500 and attempt + 1 < max_attempts) {
            var mut = result;
            mut.deinit(allocator);
            std.time.sleep(delay_ms * std.time.ns_per_ms);
            delay_ms *= 2;
            continue;
        }
        return result;
    }
}

fn integrationHeadersAlloc(allocator: std.mem.Allocator, integration: []const u8, api_key: []const u8) ![]std.http.Header {
    var list = std.ArrayList(std.http.Header).init(allocator);
    errdefer list.deinit();
    try list.append(.{ .name = "Content-Type", .value = "application/json" });
    try list.append(.{ .name = "Accept", .value = "application/json" });
    try list.append(.{ .name = "x-api-key", .value = try allocator.dupe(u8, api_key) });
    try list.append(.{ .name = "x-integration", .value = try allocator.dupe(u8, integration) });
    try list.append(.{ .name = "User-Agent", .value = "exa-mcp-zig/1.0" });
    return try list.toOwnedSlice();
}

fn freeHeaders(allocator: std.mem.Allocator, headers: []std.http.Header) void {
    for (headers) |h| {
        if (std.mem.eql(u8, h.name, "x-api-key") or std.mem.eql(u8, h.name, "x-integration")) {
            allocator.free(h.value);
        }
    }
    allocator.free(headers);
}

fn jsonEscape(writer: anytype, s: []const u8) !void {
    try writer.writeByte('"');
    for (s) |c| {
        switch (c) {
            '"' => try writer.writeAll("\\\\\\""),
            '\\\\' => try writer.writeAll("\\\\\\\\"),
            '\\n' => try writer.writeAll("\\\\n"),
            '\\r' => try writer.writeAll("\\\\r"),
            '\\t' => try writer.writeAll("\\\\t"),
            0x08 => try writer.writeAll("\\\\b"),
            0x0c => try writer.writeAll("\\\\f"),
            else => {
                if (c < 0x20) {
                    try writer.print("\\\\u{x:0>4}", .{c});
                } else {
                    try writer.writeByte(c);
                }
            },
        }
    }
    try writer.writeByte('"');
}

fn writeJsonValue(writer: anytype, value: std.json.Value, indent: usize, depth: usize) !void {
    switch (value) {
        .null => try writer.writeAll("null"),
        .bool => |b| try writer.writeAll(if (b) "true" else "false"),
        .integer => |i| try writer.print("{d}", .{i}),
        .float => |f| try writer.print("{d}", .{f}),
        .number_string => |s| try writer.writeAll(s),
        .string => |s| try jsonEscape(writer, s),
        .array => |arr| {
            if (arr.items.len == 0) {
                try writer.writeAll("[]");
                return;
            }
            try writer.writeByte('[');
            for (arr.items, 0..) |item, idx| {
                if (idx != 0) try writer.writeByte(',');
                if (indent > 0) {
                    try writer.writeByte('\\n');
                    try writer.writeByteNTimes(' ', (depth + 1) * indent);
                }
                try writeJsonValue(writer, item, indent, depth + 1);
            }
            if (indent > 0) {
                try writer.writeByte('\\n');
                try writer.writeByteNTimes(' ', depth * indent);
            }
            try writer.writeByte(']');
        },
        .object => |obj| {
            if (obj.count() == 0) {
                try writer.writeAll("{}");
                return;
            }
            try writer.writeByte('{');
            var it = obj.iterator();
            var first = true;
            while (it.next()) |entry| {
                if (!first) try writer.writeByte(',');
                first = false;
                if (indent > 0) {
                    try writer.writeByte('\\n');
                    try writer.writeByteNTimes(' ', (depth + 1) * indent);
                }
                try jsonEscape(writer, entry.key_ptr.*);
                try writer.writeAll(if (indent > 0) ": " else ":");
                try writeJsonValue(writer, entry.value_ptr.*, indent, depth + 1);
            }
            if (indent > 0) {
                try writer.writeByte('\\n');
                try writer.writeByteNTimes(' ', depth * indent);
            }
            try writer.writeByte('}');
        },
    }
}

fn jsonStringify(allocator: std.mem.Allocator, value: std.json.Value, indent: usize) ![]u8 {
    var buf = std.ArrayList(u8).init(allocator);
    errdefer buf.deinit();
    try writeJsonValue(buf.writer(), value, indent, 0);
    return try buf.toOwnedSlice();
}

const SearchArgs = struct {
    objective: []const u8,
    search_queries: ?[][]const u8 = null,
    type_str: ?[]const u8 = null,
    num_results: ?u32 = null,
    highlight_max_characters: ?u32 = null,
    output_schema: ?std.json.Value = null,
    system_prompt: ?[]const u8 = null,
    structured_output: ?bool = null,
};

fn parseArgs(allocator: std.mem.Allocator, args_value: std.json.Value) !SearchArgs {
    if (args_value != .object) return error.InvalidArguments;
    const obj = args_value.object;

    var args: SearchArgs = .{ .objective = "" };

    if (obj.get("objective")) |v| {
        if (v != .string) return error.InvalidArguments;
        args.objective = try allocator.dupe(u8, v.string);
    } else {
        return error.MissingObjective;
    }

    if (obj.get("search_queries")) |v| {
        if (v == .array) {
            const arr = v.array;
            const queries = try allocator.alloc([]const u8, arr.items.len);
            for (arr.items, 0..) |item, i| {
                if (item != .string) return error.InvalidArguments;
                queries[i] = try allocator.dupe(u8, item.string);
            }
            args.search_queries = queries;
        }
    }

    if (obj.get("type")) |v| {
        if (v == .string) {
            if (!std.mem.eql(u8, v.string, "deep") and !std.mem.eql(u8, v.string, "deep-reasoning")) {
                return error.InvalidType;
            }
            args.type_str = try allocator.dupe(u8, v.string);
        }
    }

    if (obj.get("numResults")) |v| {
        switch (v) {
            .integer => |i| args.num_results = @intCast(i),
            .float => |f| args.num_results = @intFromFloat(f),
            .string => |s| args.num_results = std.fmt.parseInt(u32, s, 10) catch null,
            else => {},
        }
    }

    if (obj.get("highlightMaxCharacters")) |v| {
        switch (v) {
            .integer => |i| args.highlight_max_characters = @intCast(i),
            .float => |f| args.highlight_max_characters = @intFromFloat(f),
            .string => |s| args.highlight_max_characters = std.fmt.parseInt(u32, s, 10) catch null,
            else => {},
        }
        if (args.highlight_max_characters) |hc| {
            if (hc < 1) return error.InvalidHighlightMax;
        }
    }

    if (obj.get("outputSchema")) |v| {
        if (v == .object) {
            args.output_schema = v;
        }
    }

    if (obj.get("systemPrompt")) |v| {
        if (v == .string) {
            if (v.string.len > 32000) return error.SystemPromptTooLong;
            args.system_prompt = try allocator.dupe(u8, v.string);
        }
    }

    if (obj.get("structuredOutput")) |v| {
        if (v == .bool) args.structured_output = v.bool;
    }

    return args;
}

fn buildSearchRequestJson(allocator: std.mem.Allocator, args: SearchArgs) ![]u8 {
    var buf = std.ArrayList(u8).init(allocator);
    errdefer buf.deinit();
    const w = buf.writer();

    try w.writeAll("{");
    try w.writeAll("\\"query\\":");
    try jsonEscape(w, args.objective);

    try w.writeAll(",\\"type\\":");
    const type_val = args.type_str orelse "deep";
    try jsonEscape(w, type_val);

    try w.writeAll(",\\"numResults\\":");
    try w.print("{d}", .{args.num_results orelse DEFAULT_NUM_RESULTS});

    try w.writeAll(",\\"contents\\":{\\"highlights\\":{\\"maxCharacters\\":");
    try w.print("{d}", .{args.highlight_max_characters orelse DEFAULT_HIGHLIGHT_CHARS});
    try w.writeAll("}}");

    if (args.output_schema) |schema| {
        try w.writeAll(",\\"outputSchema\\":");
        try writeJsonValue(w, schema, 0, 0);
    } else if (args.structured_output orelse false) {
        try w.writeAll(",\\"outputSchema\\":{\\"type\\":\\"object\\"}");
    }

    if (args.system_prompt) |sp| {
        try w.writeAll(",\\"systemPrompt\\":");
        try jsonEscape(w, sp);
    }

    if (args.search_queries) |queries| {
        if (queries.len > 0) {
            try w.writeAll(",\\"additionalQueries\\":[");
            for (queries, 0..) |q, i| {
                if (i != 0) try w.writeByte(',');
                try jsonEscape(w, q);
            }
            try w.writeByte(']');
        }
    }

    try w.writeByte('}');
    return try buf.toOwnedSlice();
}

fn sanitizeDeepSearchStructuredResponse(allocator: std.mem.Allocator, value: std.json.Value) !std.json.Value {
    if (value != .object) return value;
    var new_obj = std.json.ObjectMap.init(allocator);
    var it = value.object.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        if (std.mem.eql(u8, key, "costDollars") or
            std.mem.eql(u8, key, "requestId") or
            std.mem.eql(u8, key, "searchId"))
        {
            continue;
        }
        try new_obj.put(try allocator.dupe(u8, key), entry.value_ptr.*);
    }
    return std.json.Value{ .object = new_obj };
}

const ToolResult = struct {
    json: std.json.Value,
    arena: *std.heap.ArenaAllocator,

    fn deinit(self: *ToolResult) void {
        const child = self.arena.child_allocator;
        self.arena.deinit();
        child.destroy(self.arena);
    }
};

fn makeTextContent(allocator: std.mem.Allocator, text: []const u8, search_time: ?f64) !std.json.Value {
    var obj = std.json.ObjectMap.init(allocator);
    try obj.put("type", std.json.Value{ .string = try allocator.dupe(u8, "text") });
    try obj.put("text", std.json.Value{ .string = try allocator.dupe(u8, text) });
    if (search_time) |st| {
        var meta = std.json.ObjectMap.init(allocator);
        try meta.put("searchTime", std.json.Value{ .float = st });
        try obj.put("_meta", std.json.Value{ .object = meta });
    }
    return std.json.Value{ .object = obj };
}

fn makeContentResult(allocator: std.mem.Allocator, content_item: std.json.Value) !std.json.Value {
    var arr = std.json.Array.init(allocator);
    try arr.append(content_item);
    var obj = std.json.ObjectMap.init(allocator);
    try obj.put("content", std.json.Value{ .array = arr });
    return std.json.Value{ .object = obj };
}

fn formatToolError(allocator: std.mem.Allocator, e: anyerror, tool_name: []const u8, user_provided_api_key: bool) !std.json.Value {
    const msg = try std.fmt.allocPrint(allocator, "Error in tool '{s}': {s}{s}", .{
        tool_name,
        @errorName(e),
        if (user_provided_api_key) " (using user-provided API key)" else "",
    });
    defer allocator.free(msg);

    var content_obj = std.json.ObjectMap.init(allocator);
    try content_obj.put("type", std.json.Value{ .string = try allocator.dupe(u8, "text") });
    try content_obj.put("text", std.json.Value{ .string = try allocator.dupe(u8, msg) });

    var arr = std.json.Array.init(allocator);
    try arr.append(std.json.Value{ .object = content_obj });

    var result = std.json.ObjectMap.init(allocator);
    try result.put("content", std.json.Value{ .array = arr });
    try result.put("isError", std.json.Value{ .bool = true });
    return std.json.Value{ .object = result };
}

fn handleDeepSearch(
    allocator: std.mem.Allocator,
    arena_alloc: std.mem.Allocator,
    args_value: std.json.Value,
    config: IntegrationConfig,
) !std.json.Value {
    const request_id = try makeRequestId(arena_alloc);
    const logger = createRequestLogger(arena_alloc, request_id, "deep_search_exa");

    var args = parseArgs(arena_alloc, args_value) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    _ = &args;

    logger.start(args.objective);

    if (config.exa_api_key.len == 0) {
        logger.log("Missing EXA_API_KEY");
        return formatToolError(arena_alloc, error.MissingApiKey, "deep_search_exa", config.user_provided_api_key);
    }

    const body = buildSearchRequestJson(arena_alloc, args) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };

    if (args.output_schema != null) {
        logger.log("Using custom output schema");
    } else if (args.structured_output orelse false) {
        logger.log("Using default structured output");
    }

    if (args.system_prompt != null) {
        logger.log("Using system prompt");
    }

    if (args.search_queries) |q| {
        if (q.len > 0) {
            logger.logFmt("Using {d} additional queries", .{q.len});
        } else {
            logger.log("Using automatic query expansion");
        }
    } else {
        logger.log("Using automatic query expansion");
    }

    checkpoint("deep_search_request_prepared");
    logger.log("Sending deep search request to Exa API");

    const url = try std.fmt.allocPrint(arena_alloc, "{s}{s}", .{ EXA_BASE_URL, SEARCH_ENDPOINT });
    const headers = try integrationHeadersAlloc(allocator, "deep-search-mcp", config.exa_api_key);
    defer freeHeaders(allocator, headers);

    var http_resp = retryWithBackoff(allocator, url, headers, body) catch |e| {
        logger.err(e);
        checkpoint("deep_search_complete");
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    defer http_resp.deinit(allocator);

    checkpoint("deep_search_response_received");
    logger.log("Received response from Exa API");

    if (http_resp.status >= 400) {
        logger.logFmt("HTTP error status: {d}", .{http_resp.status});
        const e = error.HttpError;
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    }

    if (http_resp.body.len == 0) {
        logger.log("Warning: Empty response from Exa API");
        checkpoint("deep_search_complete");
        const item = try makeTextContent(arena_alloc, "No search results found. Please try a different query.", null);
        return try makeContentResult(arena_alloc, item);
    }

    var parsed = std.json.parseFromSlice(std.json.Value, arena_alloc, http_resp.body, .{}) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    const data = parsed.value;

    if (args.output_schema != null or (args.structured_output orelse false)) {
        const sanitized = try sanitizeDeepSearchStructuredResponse(arena_alloc, data);
        const text = try jsonStringify(arena_alloc, sanitized, 2);
        logger.logFmt("Structured response prepared with {d} characters", .{text.len});
        const item = try makeTextContent(arena_alloc, text, null);
        const result = try makeContentResult(arena_alloc, item);
        checkpoint("deep_search_complete");
        logger.complete();
        return result;
    }

    var parts = std.ArrayList([]const u8).init(arena_alloc);

    var output_obj: ?std.json.ObjectMap = null;
    if (data == .object) {
        if (data.object.get("output")) |o| {
            if (o == .object) output_obj = o.object;
        }
    }

    if (output_obj) |out| {
        if (out.get("content")) |c| {
            if (c == .string) {
                const ans = try std.fmt.allocPrint(arena_alloc, "## Answer\\n\\n{s}", .{c.string});
                try parts.append(ans);
            }
        }
    }

    if (output_obj) |out| {
        if (out.get("grounding")) |g| {
            if (g == .array) {
                var all_citations = std.ArrayList([]const u8).init(arena_alloc);
                for (g.array.items) |item| {
                    if (item != .object) continue;
                    if (item.object.get("citations")) |cits| {
                        if (cits != .array) continue;
                        for (cits.array.items) |cit| {
                            if (cit != .object) continue;
                            const title = if (cit.object.get("title")) |t| (if (t == .string) t.string else "") else "";
                            const url_v = if (cit.object.get("url")) |u| (if (u == .string) u.string else "") else "";
                            const line = try std.fmt.allocPrint(arena_alloc, "- [{s}]({s})", .{ title, url_v });
                            try all_citations.append(line);
                        }
                    }
                }
                if (all_citations.items.len > 0) {
                    const joined = try std.mem.join(arena_alloc, "\\n", all_citations.items);
                    const sec = try std.fmt.allocPrint(arena_alloc, "## Citations\\n\\n{s}", .{joined});
                    try parts.append(sec);
                }
            }
        }
    }

    if (data == .object) {
        if (data.object.get("results")) |r| {
            if (r == .array and r.array.items.len > 0) {
                var result_lines = std.ArrayList([]const u8).init(arena_alloc);
                for (r.array.items, 0..) |res, i| {
                    if (res != .object) continue;
                    var lines = std.ArrayList([]const u8).init(arena_alloc);
                    const title = if (res.object.get("title")) |t| (if (t == .string) t.string else "Untitled") else "Untitled";
                    const url_v = if (res.object.get("url")) |u| (if (u == .string) u.string else "") else "";
                    try lines.append(try std.fmt.allocPrint(arena_alloc, "### {d}. {s}", .{ i + 1, title }));
                    try lines.append(try std.fmt.allocPrint(arena_alloc, "**URL:** {s}", .{url_v}));
                    if (res.object.get("publishedDate")) |pd| {
                        if (pd == .string) {
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "**Published:** {s}", .{pd.string}));
                        }
                    }
                    if (res.object.get("image")) |img| {
                        if (img == .string) {
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "**Image:** {s}", .{img.string}));
                        }
                    }
                    if (res.object.get("highlights")) |hl| {
                        if (hl == .array and hl.array.items.len > 0) {
                            var hl_strs = std.ArrayList([]const u8).init(arena_alloc);
                            for (hl.array.items) |h| {
                                if (h == .string) try hl_strs.append(h.string);
                            }
                            const hl_joined = try std.mem.join(arena_alloc, "\\n\\n", hl_strs.items);
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "\\n{s}", .{hl_joined}));
                        }
                    }
                    const block = try std.mem.join(arena_alloc, "\\n", lines.items);
                    try result_lines.append(block);
                }
                if (result_lines.items.len > 0) {
                    const joined = try std.mem.join(arena_alloc, "\\n\\n---\\n\\n", result_lines.items);
                    const sec = try std.fmt.allocPrint(arena_alloc, "## Results\\n\\n{s}", .{joined});
                    try parts.append(sec);
                }
            }
        }
    }

    var search_time: ?f64 = null;
    if (data == .object) {
        if (data.object.get("searchTime")) |st| {
            switch (st) {
                .float => |f| search_time = f,
                .integer => |i| search_time = @floatFromInt(i),
                else => {},
            }
        }
    }

    const text = if (parts.items.len > 0)
