        try arr.append(try buildToolListEntry(aa));
        var result = std.json.ObjectMap.init(aa);
        try result.put("tools", std.json.Value{ .array = arr });
        try writeJsonRpcResponse(writer, aa, id, std.json.Value{ .object = result }, null, null);
        return;
    }

    if (std.mem.eql(u8, method, "tools/call")) {
        const params = root.object.get("params") orelse {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid params");
            return;
        };
        if (params != .object) {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid params");
            return;
        }
        const name_v = params.object.get("name") orelse {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Missing tool name");
            return;
        };
        if (name_v != .string) {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid tool name");
            return;
        }
        if (!std.mem.eql(u8, name_v.string, "deep_search_exa")) {
