    defer line_buf.deinit();

    while (true) {
        line_buf.clearRetainingCapacity();
        stdin.streamUntilDelimiter(line_buf.writer(), '\\n', null) catch |e| switch (e) {
            error.EndOfStream => break,
            else => return e,
