    try jsonEscape(w, args.objective);

    try w.writeAll(",\\"type\\":");
    const type_val = args.type_str orelse "deep";
    try jsonEscape(w, type_val);

    try w.writeAll(",\\"numResults\\":");
    try w.print("{d}", .{args.num_results orelse DEFAULT_NUM_RESULTS});

    try w.writeAll(",\\"contents\\":{\\"highlights\\":{\\"maxCharacters\\":");
    try w.print("{d}", .{args.highlight_max_characters orelse DEFAULT_HIGHLIGHT_CHARS});
    try w.writeAll("}}");

    if (args.output_schema) |schema| {
        try w.writeAll(",\\"outputSchema\\":");
        try writeJsonValue(w, schema, 0, 0);
    } else if (args.structured_output orelse false) {
        try w.writeAll(",\\"outputSchema\\":{\\"type\\":\\"object\\"}");
    }

    if (args.system_prompt) |sp| {
        try w.writeAll(",\\"systemPrompt\\":");
        try jsonEscape(w, sp);
    }

    if (args.search_queries) |queries| {
        if (queries.len > 0) {
            try w.writeAll(",\\"additionalQueries\\":[");
            for (queries, 0..) |q, i| {
                if (i != 0) try w.writeByte(',');
                try jsonEscape(w, q);
            }
            try w.writeByte(']');
        }
    }

    try w.writeByte('}');
    return try buf.toOwnedSlice();
}

fn sanitizeDeepSearchStructuredResponse(allocator: std.mem.Allocator, value: std.json.Value) !std.json.Value {
    if (value != .object) return value;
    var new_obj = std.json.ObjectMap.init(allocator);
    var it = value.object.iterator();
    while (it.next()) |entry| {
        const key = entry.key_ptr.*;
        if (std.mem.eql(u8, key, "costDollars") or
            std.mem.eql(u8, key, "requestId") or
            std.mem.eql(u8, key, "searchId"))
        {
            continue;
        }
        try new_obj.put(try allocator.dupe(u8, key), entry.value_ptr.*);
    }
    return std.json.Value{ .object = new_obj };
}

const ToolResult = struct {
    json: std.json.Value,
    arena: *std.heap.ArenaAllocator,

    fn deinit(self: *ToolResult) void {
        const child = self.arena.child_allocator;
        self.arena.deinit();
        child.destroy(self.arena);
    }
};

fn makeTextContent(allocator: std.mem.Allocator, text: []const u8, search_time: ?f64) !std.json.Value {
    var obj = std.json.ObjectMap.init(allocator);
    try obj.put("type", std.json.Value{ .string = try allocator.dupe(u8, "text") });
    try obj.put("text", std.json.Value{ .string = try allocator.dupe(u8, text) });
    if (search_time) |st| {
        var meta = std.json.ObjectMap.init(allocator);
        try meta.put("searchTime", std.json.Value{ .float = st });
        try obj.put("_meta", std.json.Value{ .object = meta });
    }
    return std.json.Value{ .object = obj };
}

fn makeContentResult(allocator: std.mem.Allocator, content_item: std.json.Value) !std.json.Value {
    var arr = std.json.Array.init(allocator);
    try arr.append(content_item);
    var obj = std.json.ObjectMap.init(allocator);
    try obj.put("content", std.json.Value{ .array = arr });
    return std.json.Value{ .object = obj };
}

fn formatToolError(allocator: std.mem.Allocator, e: anyerror, tool_name: []const u8, user_provided_api_key: bool) !std.json.Value {
    const msg = try std.fmt.allocPrint(allocator, "Error in tool '{s}': {s}{s}", .{
        tool_name,
        @errorName(e),
        if (user_provided_api_key) " (using user-provided API key)" else "",
    });
    defer allocator.free(msg);

    var content_obj = std.json.ObjectMap.init(allocator);
    try content_obj.put("type", std.json.Value{ .string = try allocator.dupe(u8, "text") });
    try content_obj.put("text", std.json.Value{ .string = try allocator.dupe(u8, msg) });

    var arr = std.json.Array.init(allocator);
    try arr.append(std.json.Value{ .object = content_obj });

    var result = std.json.ObjectMap.init(allocator);
    try result.put("content", std.json.Value{ .array = arr });
    try result.put("isError", std.json.Value{ .bool = true });
    return std.json.Value{ .object = result };
}

fn handleDeepSearch(
    allocator: std.mem.Allocator,
    arena_alloc: std.mem.Allocator,
    args_value: std.json.Value,
    config: IntegrationConfig,
) !std.json.Value {
    const request_id = try makeRequestId(arena_alloc);
    const logger = createRequestLogger(arena_alloc, request_id, "deep_search_exa");

    var args = parseArgs(arena_alloc, args_value) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    _ = &args;

    logger.start(args.objective);

    if (config.exa_api_key.len == 0) {
        logger.log("Missing EXA_API_KEY");
        return formatToolError(arena_alloc, error.MissingApiKey, "deep_search_exa", config.user_provided_api_key);
    }

    const body = buildSearchRequestJson(arena_alloc, args) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };

    if (args.output_schema != null) {
        logger.log("Using custom output schema");
    } else if (args.structured_output orelse false) {
        logger.log("Using default structured output");
    }

    if (args.system_prompt != null) {
        logger.log("Using system prompt");
    }

    if (args.search_queries) |q| {
        if (q.len > 0) {
            logger.logFmt("Using {d} additional queries", .{q.len});
        } else {
            logger.log("Using automatic query expansion");
        }
    } else {
        logger.log("Using automatic query expansion");
    }

    checkpoint("deep_search_request_prepared");
    logger.log("Sending deep search request to Exa API");

    const url = try std.fmt.allocPrint(arena_alloc, "{s}{s}", .{ EXA_BASE_URL, SEARCH_ENDPOINT });
    const headers = try integrationHeadersAlloc(allocator, "deep-search-mcp", config.exa_api_key);
    defer freeHeaders(allocator, headers);

    var http_resp = retryWithBackoff(allocator, url, headers, body) catch |e| {
        logger.err(e);
        checkpoint("deep_search_complete");
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    defer http_resp.deinit(allocator);

    checkpoint("deep_search_response_received");
    logger.log("Received response from Exa API");

    if (http_resp.status >= 400) {
        logger.logFmt("HTTP error status: {d}", .{http_resp.status});
        const e = error.HttpError;
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    }

    if (http_resp.body.len == 0) {
        logger.log("Warning: Empty response from Exa API");
        checkpoint("deep_search_complete");
        const item = try makeTextContent(arena_alloc, "No search results found. Please try a different query.", null);
        return try makeContentResult(arena_alloc, item);
    }

    var parsed = std.json.parseFromSlice(std.json.Value, arena_alloc, http_resp.body, .{}) catch |e| {
        logger.err(e);
        return formatToolError(arena_alloc, e, "deep_search_exa", config.user_provided_api_key);
    };
    const data = parsed.value;

    if (args.output_schema != null or (args.structured_output orelse false)) {
        const sanitized = try sanitizeDeepSearchStructuredResponse(arena_alloc, data);
        const text = try jsonStringify(arena_alloc, sanitized, 2);
        logger.logFmt("Structured response prepared with {d} characters", .{text.len});
        const item = try makeTextContent(arena_alloc, text, null);
        const result = try makeContentResult(arena_alloc, item);
        checkpoint("deep_search_complete");
        logger.complete();
        return result;
    }

    var parts = std.ArrayList([]const u8).init(arena_alloc);

    var output_obj: ?std.json.ObjectMap = null;
    if (data == .object) {
        if (data.object.get("output")) |o| {
            if (o == .object) output_obj = o.object;
        }
    }

    if (output_obj) |out| {
        if (out.get("content")) |c| {
            if (c == .string) {
                const ans = try std.fmt.allocPrint(arena_alloc, "## Answer\\n\\n{s}", .{c.string});
                try parts.append(ans);
            }
        }
    }

    if (output_obj) |out| {
        if (out.get("grounding")) |g| {
            if (g == .array) {
                var all_citations = std.ArrayList([]const u8).init(arena_alloc);
                for (g.array.items) |item| {
                    if (item != .object) continue;
                    if (item.object.get("citations")) |cits| {
                        if (cits != .array) continue;
                        for (cits.array.items) |cit| {
                            if (cit != .object) continue;
                            const title = if (cit.object.get("title")) |t| (if (t == .string) t.string else "") else "";
                            const url_v = if (cit.object.get("url")) |u| (if (u == .string) u.string else "") else "";
                            const line = try std.fmt.allocPrint(arena_alloc, "- [{s}]({s})", .{ title, url_v });
                            try all_citations.append(line);
                        }
                    }
                }
                if (all_citations.items.len > 0) {
                    const joined = try std.mem.join(arena_alloc, "\\n", all_citations.items);
                    const sec = try std.fmt.allocPrint(arena_alloc, "## Citations\\n\\n{s}", .{joined});
                    try parts.append(sec);
                }
            }
        }
    }

    if (data == .object) {
        if (data.object.get("results")) |r| {
            if (r == .array and r.array.items.len > 0) {
                var result_lines = std.ArrayList([]const u8).init(arena_alloc);
                for (r.array.items, 0..) |res, i| {
                    if (res != .object) continue;
                    var lines = std.ArrayList([]const u8).init(arena_alloc);
                    const title = if (res.object.get("title")) |t| (if (t == .string) t.string else "Untitled") else "Untitled";
                    const url_v = if (res.object.get("url")) |u| (if (u == .string) u.string else "") else "";
                    try lines.append(try std.fmt.allocPrint(arena_alloc, "### {d}. {s}", .{ i + 1, title }));
                    try lines.append(try std.fmt.allocPrint(arena_alloc, "**URL:** {s}", .{url_v}));
                    if (res.object.get("publishedDate")) |pd| {
                        if (pd == .string) {
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "**Published:** {s}", .{pd.string}));
                        }
                    }
                    if (res.object.get("image")) |img| {
                        if (img == .string) {
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "**Image:** {s}", .{img.string}));
                        }
                    }
                    if (res.object.get("highlights")) |hl| {
                        if (hl == .array and hl.array.items.len > 0) {
                            var hl_strs = std.ArrayList([]const u8).init(arena_alloc);
                            for (hl.array.items) |h| {
                                if (h == .string) try hl_strs.append(h.string);
                            }
                            const hl_joined = try std.mem.join(arena_alloc, "\\n\\n", hl_strs.items);
                            try lines.append(try std.fmt.allocPrint(arena_alloc, "\\n{s}", .{hl_joined}));
                        }
                    }
                    const block = try std.mem.join(arena_alloc, "\\n", lines.items);
                    try result_lines.append(block);
                }
                if (result_lines.items.len > 0) {
                    const joined = try std.mem.join(arena_alloc, "\\n\\n---\\n\\n", result_lines.items);
                    const sec = try std.fmt.allocPrint(arena_alloc, "## Results\\n\\n{s}", .{joined});
                    try parts.append(sec);
                }
            }
        }
    }

    var search_time: ?f64 = null;
    if (data == .object) {
        if (data.object.get("searchTime")) |st| {
            switch (st) {
                .float => |f| search_time = f,
                .integer => |i| search_time = @floatFromInt(i),
                else => {},
            }
        }
    }

    const text = if (parts.items.len > 0)
        try std.mem.join(arena_alloc, "\\n\\n---\\n\\n", parts.items)
    else
        try arena_alloc.dupe(u8, "No results found. Please try a different query.");

    logger.logFmt("Response prepared with {d} characters", .{text.len});

    const item = try makeTextContent(arena_alloc, text, search_time);
    const result = try makeContentResult(arena_alloc, item);

    checkpoint("deep_search_complete");
    logger.complete();
    return result;
}

const TOOL_DESCRIPTION =
    \\\\[Deprecated: Use web_search_advanced_exa instead] Deep search with automatic query expansion for thorough research. Generates multiple search variations to find results from multiple angles, then synthesizes a short answer with citations.
    \\\\
    \\\\Best for: Complex questions needing information from multiple angles.
    \\\\Returns: A synthesized answer with citations, plus individual search results with highlights. When structuredOutput is enabled, returns structured JSON instead of markdown.
    \\\\Note: Requires an Exa API key. 'deep' mode takes 4-12s, 'deep-reasoning' takes 12-50s.
;

fn buildToolSchema(allocator: std.mem.Allocator) !std.json.Value {
    var schema = std.json.ObjectMap.init(allocator);
    try schema.put("type", std.json.Value{ .string = try allocator.dupe(u8, "object") });

    var properties = std.json.ObjectMap.init(allocator);

    var objective = std.json.ObjectMap.init(allocator);
    try objective.put("type", std.json.Value{ .string = try allocator.dupe(u8, "string") });
    try objective.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Natural language description of what the web search is looking for. Try to make the search query atomic - looking for a specific piece of information.") });
    try properties.put("objective", std.json.Value{ .object = objective });

    var sq = std.json.ObjectMap.init(allocator);
    try sq.put("type", std.json.Value{ .string = try allocator.dupe(u8, "array") });
    var sq_items = std.json.ObjectMap.init(allocator);
    try sq_items.put("type", std.json.Value{ .string = try allocator.dupe(u8, "string") });
    try sq.put("items", std.json.Value{ .object = sq_items });
    try sq.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Optional list of keyword search queries related to the objective. Limited to 5 entries of up to 5 words each (~200 characters).") });
    try properties.put("search_queries", std.json.Value{ .object = sq });

    var t = std.json.ObjectMap.init(allocator);
    try t.put("type", std.json.Value{ .string = try allocator.dupe(u8, "string") });
    var enum_arr = std.json.Array.init(allocator);
    try enum_arr.append(std.json.Value{ .string = try allocator.dupe(u8, "deep") });
    try enum_arr.append(std.json.Value{ .string = try allocator.dupe(u8, "deep-reasoning") });
    try t.put("enum", std.json.Value{ .array = enum_arr });
    try t.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Search depth - 'deep': fast deep search (4-12s, default), 'deep-reasoning': thorough with reasoning (12-50s)") });
    try properties.put("type", std.json.Value{ .object = t });

    var nr = std.json.ObjectMap.init(allocator);
    try nr.put("type", std.json.Value{ .string = try allocator.dupe(u8, "number") });
    try nr.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Number of search results to return (must be a number, default: 8)") });
    try properties.put("numResults", std.json.Value{ .object = nr });

    var hmc = std.json.ObjectMap.init(allocator);
    try hmc.put("type", std.json.Value{ .string = try allocator.dupe(u8, "number") });
    try hmc.put("minimum", std.json.Value{ .integer = 1 });
    try hmc.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Maximum characters for highlights per result (must be a positive number, default: 4000)") });
    try properties.put("highlightMaxCharacters", std.json.Value{ .object = hmc });

    var os = std.json.ObjectMap.init(allocator);
    try os.put("type", std.json.Value{ .string = try allocator.dupe(u8, "object") });
    try os.put("description", std.json.Value{ .string = try allocator.dupe(u8, "JSON schema for structured output. Must include a 'type' field set to 'object' or 'text'. For 'object' type, optionally include 'properties' and 'required'. Max 10 total properties, max nesting depth 2. When provided, automatically enables structured output mode.") });
    try properties.put("outputSchema", std.json.Value{ .object = os });

    var sp = std.json.ObjectMap.init(allocator);
    try sp.put("type", std.json.Value{ .string = try allocator.dupe(u8, "string") });
    try sp.put("maxLength", std.json.Value{ .integer = 32000 });
    try sp.put("description", std.json.Value{ .string = try allocator.dupe(u8, "Instructions for how the deep search agent should process and format results.") });
    try properties.put("systemPrompt", std.json.Value{ .object = sp });

    var so = std.json.ObjectMap.init(allocator);
    try so.put("type", std.json.Value{ .string = try allocator.dupe(u8, "boolean") });
    try so.put("description", std.json.Value{ .string = try allocator.dupe(u8, "When true, returns a structured JSON response instead of markdown. The API will determine the appropriate structure based on the query. Prefer using outputSchema for more control over the response shape.") });
    try properties.put("structuredOutput", std.json.Value{ .object = so });

    try schema.put("properties", std.json.Value{ .object = properties });

    var required = std.json.Array.init(allocator);
    try required.append(std.json.Value{ .string = try allocator.dupe(u8, "objective") });
    try schema.put("required", std.json.Value{ .array = required });

    return std.json.Value{ .object = schema };
}

fn buildToolListEntry(allocator: std.mem.Allocator) !std.json.Value {
    var tool = std.json.ObjectMap.init(allocator);
    try tool.put("name", std.json.Value{ .string = try allocator.dupe(u8, "deep_search_exa") });
    try tool.put("description", std.json.Value{ .string = try allocator.dupe(u8, TOOL_DESCRIPTION) });
    try tool.put("inputSchema", try buildToolSchema(allocator));

    var annotations = std.json.ObjectMap.init(allocator);
    try annotations.put("readOnlyHint", std.json.Value{ .bool = true });
    try annotations.put("destructiveHint", std.json.Value{ .bool = false });
    try annotations.put("idempotentHint", std.json.Value{ .bool = false });
    try tool.put("annotations", std.json.Value{ .object = annotations });

    return std.json.Value{ .object = tool };
}

fn writeJsonRpcResponse(writer: anytype, allocator: std.mem.Allocator, id: std.json.Value, result: ?std.json.Value, err_code: ?i64, err_msg: ?[]const u8) !void {
    var resp = std.json.ObjectMap.init(allocator);
    defer resp.deinit();
    try resp.put("jsonrpc", std.json.Value{ .string = "2.0" });
    try resp.put("id", id);
    if (result) |r| {
        try resp.put("result", r);
    } else if (err_code) |ec| {
        var err_obj = std.json.ObjectMap.init(allocator);
        try err_obj.put("code", std.json.Value{ .integer = ec });
        try err_obj.put("message", std.json.Value{ .string = err_msg orelse "error" });
        try resp.put("error", std.json.Value{ .object = err_obj });
    }
    const v = std.json.Value{ .object = resp };
    const s = try jsonStringify(allocator, v, 0);
    defer allocator.free(s);
    try writer.writeAll(s);
    try writer.writeByte('\\n');
}

fn handleRequest(
    allocator: std.mem.Allocator,
    line: []const u8,
    config: IntegrationConfig,
    writer: anytype,
) !void {
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const aa = arena.allocator();

    var parsed = std.json.parseFromSlice(std.json.Value, aa, line, .{}) catch {
        return;
    };
    const root = parsed.value;
    if (root != .object) return;

    const method_v = root.object.get("method") orelse return;
    if (method_v != .string) return;
    const method = method_v.string;

    const id = root.object.get("id") orelse std.json.Value{ .null = {} };

    if (std.mem.eql(u8, method, "initialize")) {
        var result = std.json.ObjectMap.init(aa);
        try result.put("protocolVersion", std.json.Value{ .string = "2024-11-05" });
        var capabilities = std.json.ObjectMap.init(aa);
        var tools_cap = std.json.ObjectMap.init(aa);
        try capabilities.put("tools", std.json.Value{ .object = tools_cap });
        try result.put("capabilities", std.json.Value{ .object = capabilities });
        var server_info = std.json.ObjectMap.init(aa);
        try server_info.put("name", std.json.Value{ .string = "exa-deep-search-mcp" });
        try server_info.put("version", std.json.Value{ .string = "1.0.0" });
        try result.put("serverInfo", std.json.Value{ .object = server_info });
        try writeJsonRpcResponse(writer, aa, id, std.json.Value{ .object = result }, null, null);
        return;
    }

    if (std.mem.eql(u8, method, "notifications/initialized")) return;

    if (std.mem.eql(u8, method, "tools/list")) {
        var arr = std.json.Array.init(aa);
        try arr.append(try buildToolListEntry(aa));
        var result = std.json.ObjectMap.init(aa);
        try result.put("tools", std.json.Value{ .array = arr });
        try writeJsonRpcResponse(writer, aa, id, std.json.Value{ .object = result }, null, null);
        return;
    }

    if (std.mem.eql(u8, method, "tools/call")) {
        const params = root.object.get("params") orelse {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid params");
            return;
        };
        if (params != .object) {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid params");
            return;
        }
        const name_v = params.object.get("name") orelse {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Missing tool name");
            return;
        };
        if (name_v != .string) {
            try writeJsonRpcResponse(writer, aa, id, null, -32602, "Invalid tool name");
            return;
        }
        if (!std.mem.eql(u8, name_v.string, "deep_search_exa")) {
            try writeJsonRpcResponse(writer, aa, id, null, -32601, "Unknown tool");
            return;
        }
        const args_v = params.object.get("arguments") orelse std.json.Value{ .object = std.json.ObjectMap.init(aa) };

        const result = handleDeepSearch(allocator, aa, args_v, config) catch |e| {
            const v = try formatToolError(aa, e, "deep_search_exa", config.user_provided_api_key);
            try writeJsonRpcResponse(writer, aa, id, v, null, null);
            return;
        };
        try writeJsonRpcResponse(writer, aa, id, result, null, null);
        return;
    }

    try writeJsonRpcResponse(writer, aa, id, null, -32601, "Method not found");
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var env_map = try std.process.getEnvMap(allocator);
    defer env_map.deinit();

    const api_key = env_map.get("EXA_API_KEY") orelse "";
    const user_provided_str = env_map.get("USER_PROVIDED_API_KEY") orelse "";
    const user_provided = std.mem.eql(u8, user_provided_str, "true") or std.mem.eql(u8, user_provided_str, "1");

    const config = IntegrationConfig{
        .exa_api_key = api_key,
        .user_provided_api_key = user_provided,
    };

    const stdin = std.io.getStdIn().reader();
    const stdout = std.io.getStdOut().writer();
    var buffered_out = std.io.bufferedWriter(stdout);
    const w = buffered_out.writer();

    var line_buf = std.ArrayList(u8).init(allocator);
    defer line_buf.deinit();

    while (true) {
        line_buf.clearRetainingCapacity();
        stdin.streamUntilDelimiter(line_buf.writer(), '\\n', null) catch |e| switch (e) {
            error.EndOfStream => break,
            else => return e,
        };
        const trimmed = std.mem.trim(u8, line_buf.items, " \\t\\r\\n");
        if (trimmed.len == 0) continue;
        handleRequest(allocator, trimmed, config, w) catch |e| {
            std.log.err("request handling error: {s}", .{@errorName(e)});
        };
        try buffered_out.flush();
    }
}
